     1→{% comment %}
     2→  Zip Code Checker — Theme App Extension Block
     3→  Add this block to any section in the Shopify Theme Editor.
     4→  The block automatically connects to your app — no manual configuration needed.
     5→{% endcomment %}
     6→
     7→<div
     8→  id="zcc-widget-{{ block.id }}"
     9→  data-shop="{{ shop.permanent_domain }}"
    10→  data-api="{{ app.url }}"
    11→  data-block="{{ block.id }}"
    12→  {{ block.shopify_attributes }}
    13→></div>
    14→
    15→<script>
    16→(function () {
    17→  var ROOT_ID = "zcc-widget-{{ block.id }}";
    18→  var container = document.getElementById(ROOT_ID);
    19→  if (!container) return;
    20→
    21→  var SHOP = container.dataset.shop;
    22→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
    23→
    24→  // Fetch widget config, then render
    25→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
    26→    .then(function (r) { return r.json(); })
    27→    .then(function (cfg) { renderWidget(cfg); })
    28→    .catch(function () { renderWidget({}); });
    29→
    30→  function renderWidget(cfg) {
    31→    // Merge with defaults
    32→    var D = {
    33→      heading: "Check Delivery Availability",
    34→      placeholder: "Enter your zip code",
    35→      buttonText: "Check",
    36→      successMessage: "Great news! We deliver to your area.",
    37→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
    38→      notFoundMessage: "This zip code was not found in our system.",
    39→      primaryColor: "#008060",
    40→      successColor: "#008060",
    41→      errorColor: "#D72C0D",
    42→      backgroundColor: "#FFFFFF",
    43→      textColor: "#202223",
    44→      borderRadius: "8",
    45→      showEta: true,
    46→      showZone: false,
    47→      showWaitlistOnFailure: false,
    48→      customCss: "",
    49→    };
    50→    Object.keys(D).forEach(function (k) {
    51→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
    52→    });
    53→
    54→    var rad = cfg.borderRadius + "px";
    55→    var WID = "zcc-" + ROOT_ID;
    56→
    57→    // ---- Inject scoped CSS ----
    58→    var css =
    59→      "#" + WID + "{" +
    60→        "background:" + cfg.backgroundColor + ";" +
    61→        "color:" + cfg.textColor + ";" +
    62→        "border-radius:" + rad + ";" +
    63→        "padding:24px;" +
    64→        "border:1px solid #e1e3e5;" +
    65→        "max-width:480px;" +
    66→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
    67→        "box-sizing:border-box;" +
    68→      "}" +
    69→      "#" + WID + " *{box-sizing:border-box}" +
    70→      "#" + WID + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
    71→      "#" + WID + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
    72→      "#" + WID + " .zcc-input{" +
    73→        "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
    74→        "border-radius:" + rad + ";font-size:14px;outline:none;" +
    75→        "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
    76→      "}" +
    77→      "#" + WID + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
    78→      "#" + WID + " .zcc-btn{" +
    79→        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
    80→        "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
    81→        "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
    82→      "}" +
    83→      "#" + WID + " .zcc-btn:hover{opacity:.9}" +
    84→      "#" + WID + " .zcc-btn:disabled{opacity:.6;cursor:not-allowed}" +
    85→      "#" + WID + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
    86→      "#" + WID + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
    87→      "#" + WID + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
    88→      "#" + WID + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
    89→      "#" + WID + " .zcc-wl{margin-top:10px}" +
    90→      "#" + WID + " .zcc-wl-input{" +
    91→        "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
    92→        "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
    93→      "}" +
    94→      "#" + WID + " .zcc-wl-btn{" +
    95→        "background:" + cfg.errorColor + ";color:#fff;border:none;" +
    96→        "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
    97→        "cursor:pointer;width:100%;font-weight:600" +
    98→      "}" +
    99→      "#" + WID + " .zcc-wl-btn:disabled{opacity:.6;cursor:not-allowed}" +
   100→      (cfg.customCss || "");
   101→
   102→    var styleEl = document.createElement("style");
   103→    styleEl.textContent = css;
   104→    document.head.appendChild(styleEl);
   105→
   106→    // ---- Build HTML ----
   107→    container.id = WID;
   108→    container.innerHTML =
   109→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
   110→      '<div class="zcc-row">' +
   111→        '<input class="zcc-input" type="text" id="' + WID + '-inp"' +
   112→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
   113→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
   114→        '<button class="zcc-btn" id="' + WID + '-btn" type="button">' + esc(cfg.buttonText) + "</button>" +
   115→      "</div>" +
   116→      '<div id="' + WID + '-res"></div>';
   117→
   118→    var inp = document.getElementById(WID + "-inp");
   119→    var btn = document.getElementById(WID + "-btn");
   120→    var res = document.getElementById(WID + "-res");
   121→    var btnLabel = cfg.buttonText;
   122→
   123→    function checkZip() {
   124→      var zip = inp.value.trim();
   125→      if (!zip) { inp.focus(); return; }
   126→
   127→      btn.disabled = true;
   128→      btn.textContent = "\u2026";
   129→      res.innerHTML = "";
   130→
   131→      fetch(
   132→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   133→          "&zip=" + encodeURIComponent(zip)
   134→      )
   135→        .then(function (r) { return r.json(); })
   136→        .then(function (data) {
   137→          btn.disabled = false;
   138→          btn.textContent = btnLabel;
   139→
   140→          if (data.allowed) {
   141→            var html = '<div class="zcc-result ok">' + esc(data.message);
   142→            if (cfg.showEta && data.eta) {
   143→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   144→            }
   145→            if (cfg.showZone && data.zone) {
   146→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   147→            }
   148→            html += "</div>";
   149→            res.innerHTML = html;
   150→          } else {
   151→            var html = '<div class="zcc-result fail">' + esc(data.message);
   152→            if (cfg.showWaitlistOnFailure) {
   153→              html +=
   154→                '<div class="zcc-wl">' +
   155→                '<input class="zcc-wl-input" type="email" id="' + WID + '-wl-email" placeholder="Enter email to join waitlist" />' +
   156→                '<button class="zcc-wl-btn" id="' + WID + '-wl-btn" type="button">Join Waitlist</button>' +
   157→                "</div>";
   158→            }
   159→            html += "</div>";
   160→            res.innerHTML = html;
   161→
   162→            if (cfg.showWaitlistOnFailure) {
   163→              var wBtn = document.getElementById(WID + "-wl-btn");
   164→              if (wBtn) {
   165→                wBtn.addEventListener("click", function () {
   166→                  var emailEl = document.getElementById(WID + "-wl-email");
   167→                  var email = emailEl ? emailEl.value.trim() : "";
   168→                  if (!email) { if (emailEl) emailEl.focus(); return; }
   169→                  joinWaitlist(zip, email, wBtn);
   170→                });
   171→              }
   172→            }
   173→          }
   174→        })
   175→        .catch(function () {
   176→          btn.disabled = false;
   177→          btn.textContent = btnLabel;
   178→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
   179→        });
   180→    }
   181→
   182→    function joinWaitlist(zip, email, wBtn) {
   183→      wBtn.disabled = true;
   184→      wBtn.textContent = "Joining\u2026";
   185→
   186→      fetch(API_BASE + "/api/waitlist", {
   187→        method: "POST",
   188→        headers: { "Content-Type": "application/json" },
   189→        body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
   190→      })
   191→        .then(function (r) { return r.json(); })
   192→        .then(function (data) {
   193→          var wlEl = wBtn.closest(".zcc-wl");
   194→          if (data.success) {
   195→            if (wlEl) wlEl.innerHTML =
   196→              '<p style="font-size:13px;margin:6px 0 0">' +
   197→              "\u2713 You\u2019ve been added to the waitlist!" +
   198→              "</p>";
   199→          } else {
   200→            wBtn.disabled = false;
   201→            wBtn.textContent = "Join Waitlist";
   202→          }
   203→        })
   204→        .catch(function () {
   205→          wBtn.disabled = false;
   206→          wBtn.textContent = "Join Waitlist";
   207→        });
   208→    }
   209→
   210→    btn.addEventListener("click", checkZip);
   211→    inp.addEventListener("keydown", function (e) {
   212→      if (e.key === "Enter") checkZip();
   213→    });
   214→  }
   215→
   216→  function esc(str) {
   217→    return String(str)
   218→      .replace(/&/g, "&amp;")
   219→      .replace(/</g, "&lt;")
   220→      .replace(/>/g, "&gt;")
   221→      .replace(/"/g, "&quot;");
   222→  }
   223→
   224→  function escAttr(str) {
   225→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
   226→  }
   227→})();
   228→</script>
   229→
   230→{% schema %}
   231→{
   232→  "name": "Zip Code Checker",
   233→  "target": "section",
   234→  "settings": []
   235→}
   236→{% endschema %}
